{
  "sop_id": "SOP-016",
  "title": "Employee Expense Claim Approval",
  "steps": [
    {
      "step_id": "S1",
      "name": "Create and assign ticket",
      "role": "Executor",
      "type": "intake"
    },
    {
      "step_id": "S2",
      "name": "Check every line against policy limits for the claimant's grade and expense category",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S3",
      "name": "Match each line to a receipt",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S4",
      "name": "Compute the reimbursable amount and submit",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "A1",
      "name": "Approval",
      "role": "Incharge",
      "type": "approval"
    }
  ],
  "approvals": [
    {
      "stage": "Incharge",
      "condition": "always"
    }
  ],
  "dependencies": [],
  "rework_reasons": [
    "Amount mismatch",
    "Wrong quantity",
    "Incorrect category",
    "Required document missing"
  ],
  "first_pass_yield_target": 0.95
}
